// Generated required-member matrix: every required member of every readings
// wire envelope, removed and nulled, must refuse before any reading is
// published. Cases are generated by walking the single
// sharedWireStrictSpec declaration plus the resource required lists, so a new
// required member without coverage fails closed (it appears here with no
// valid base only if the base builders omit it, which the valid controls
// catch). Each case runs through the production admission sequence:
// readSharedWireMessage, the caller presence check, then the attested
// envelope validator.

type requiredMemberCase struct {
	name       string
	parentPath []string
	member     string
	nullable   bool
}

func collectRequiredMemberCases(spec *strictJSONSpec, path []string, cases *[]requiredMemberCase) {
	nullable := map[string]bool{}
	for _, member := range spec.nullable {
		nullable[member] = true
	}
	for _, member := range spec.required {
		name := member
		if len(path) > 0 {
			name = strings.Join(path, ".") + "." + member
		}
		*cases = append(*cases, requiredMemberCase{name: name, parentPath: append([]string(nil), path...), member: member, nullable: nullable[member]})
	}
	names := make([]string, 0, len(spec.object))
	for name := range spec.object {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		child := spec.object[name]
		if child == nil {
			continue
		}
		if child.elements != nil {
			collectRequiredMemberCases(child.elements, append(path, name+"[0]"), cases)
			continue
		}
		if child.object != nil {
			collectRequiredMemberCases(child, append(path, name), cases)
		}
	}
}

func requiredMatrixIdentity() (FileIdentity, ProcessStartTime, ProcessStartTime) {
	return FileIdentity{Dev: 1, Ino: 2, Size: 3, Mode: 0o755},
		ProcessStartTime{Seconds: 1000, Microseconds: 0},
		ProcessStartTime{Seconds: 2000, Microseconds: 0}
}

func requiredMatrixBroker() map[string]any {
	identity, start, _ := requiredMatrixIdentity()
	return map[string]any{
		"pid": 100, "pgid": 100, "sid": 100,
		"start_time":          map[string]any{"seconds": start.Seconds, "microseconds": start.Microseconds},
		"uid":                 501,
		"exec_path":           "/bin/broker",
		"argv":                []string{"broker"},
		"executable_identity": map[string]any{"dev": identity.Dev, "ino": identity.Ino, "size": identity.Size, "mode": identity.Mode},
	}
}

func requiredMatrixRuntime(endpoint string) map[string]any {
	identity, _, start := requiredMatrixIdentity()
	shape := func(path string, argv []string) map[string]any {
		return map[string]any{"exec_path": path, "argv": argv}
	}
	return map[string]any{
		"pid": 200, "pgid": 200,
		"start_time": map[string]any{"seconds": start.Seconds, "microseconds": start.Microseconds},
		"uid":        501,
		"pre_exec":   shape("/bin/launcher", []string{"launcher"}), "post_exec": shape("/bin/runtime", []string{"runtime", "serve"}),
		"cwd":                 "/tmp/cwd",
		"endpoint":            endpoint,
		"executable_identity": map[string]any{"dev": identity.Dev, "ino": identity.Ino, "size": identity.Size, "mode": identity.Mode},
		"exec_plan_digest":    "abc123",
		"stage":               "running",
	}
}

// The zero-heavy valid sharing: linger, restart limit and backoffs are
// explicit zeros, which must stay valid while missing/null refuse.
func requiredMatrixSharing(provider bool) map[string]any {
	sharing := map[string]any{
		"mode": "shared", "linger_seconds": 0, "max_leases": 8,
		"max_segment_bytes": 1048576, "max_segments": 7,
		"heartbeat_interval_seconds": 15, "lease_stale_seconds": 60,
		"broker_start_timeout_seconds": 61, "restart_limit": 0,
		"restart_initial_backoff_seconds": 0, "restart_max_backoff_seconds": 0,
		"stable_run_seconds": 60, "quarantine_seconds": 30,
		"resource_pressure_mode": "disabled",
	}
	if provider {
		sharing["resource_pressure_mode"] = "provider"
		sharing["resource_pressure"] = map[string]any{
			"observation_path": "/observations", "observation_timeout_milliseconds": 1000,
			"pressure_threshold_bytes": 2000, "recovery_threshold_bytes": 1000,
			"eviction_grace_seconds": 0,
			"pressure_action":        "refuse-new-drain-idle", "unknown_action": "refuse-new", "busy_action": "observe",
		}
	}
	return sharing
}

func requiredMatrixLease(env string, engine map[string]any) map[string]any {
	now := time.Now().UTC().Format(time.RFC3339Nano)
	return map[string]any{
		"lease_id": "0123456789abcdef0123456789abcdef", "lease_lifetime": "client_process",
		"engine_identity": engine,
		"client_key":      "test-client", "client_pid": 300,
		"client_start_time": map[string]any{"seconds": int64(1), "microseconds": 0},
		"runtime_key":       "runtime-key-fixture", "profile_digest": "profile-digest-fixture", "endpoint": env,
		"runtime_pid": 200, "granted_at": now, "last_heartbeat_at": now,
		"state": "held", "age": 1000000, "heartbeat_age": 1000000,
	}
}

// requiredMatrixLeaseRecord is the singular acquire-flow record: the lease
// status wrapper members (state, age, heartbeat_age) belong to status rows
// only.
func requiredMatrixLeaseRecord(endpoint string, engine map[string]any) map[string]any {
	record := requiredMatrixLease(endpoint, engine)
	delete(record, "state")
	delete(record, "age")
	delete(record, "heartbeat_age")
	return record
}

func requiredMatrixResources() map[string]any {
	return map[string]any{
		"schema": SharedRuntimeResourceStatusSchema, "source": "provider-observed",
		"state": "healthy", "admission": "admitted", "observed_at": time.Now().UTC().Format(time.RFC3339Nano),
		"loaded_model_memory": map[string]any{"state": "healthy", "bytes": 100, "pressure_at_bytes": 1000, "recovery_at_bytes": 800},
		"inference":           map[string]any{"state": "idle"},
		"policy":              map[string]any{"mode": "provider", "eviction_grace_seconds": 0, "pressure_action": "refuse-new-drain-idle", "unknown_action": "refuse-new", "busy_action": "observe"},
	}
}

type requiredMatrixBase struct {
	name       string
	frame      map[string]any
	kind       string // hello_ok, status, or decode-only
	attested   sharedAttestedRuntime
	resolved   sharedResolvedProfile
	attestedOK bool
}

func requiredMatrixBases() []requiredMatrixBase {
	endpoint := "http://127.0.0.1:18011/v1"
	engine := map[string]any{"name": "engine-name", "key": "engine-key"}
	identity, brokerStart, runtimeStart := requiredMatrixIdentity()
	attested := sharedAttestedRuntime{
		broker:  SharedBrokerIdentity{PID: 100, StartTime: brokerStart, ExecutableIdentity: identity},
		runtime: SharedRuntimeProcessRecord{PID: 200, StartTime: runtimeStart, Endpoint: endpoint, ExecutableIdentity: identity},
	}
	resolved := sharedResolvedProfile{
		RuntimeKey: "runtime-key-fixture", ProfileDigest: "profile-digest-fixture",
		EngineIdentity: SharedRuntimeEngineIdentity{Name: "engine-name", Key: "engine-key"},
	}
	resolved.Profile.BaseURL = endpoint
	resolved.Profile.Runtime.StartupTimeoutSeconds = 1
	resolved.Profile.Runtime.ShutdownTimeoutSeconds = 30
	hello := func(provider bool) map[string]any {
		return map[string]any{
			"type": "hello_ok", "protocol_version": 7,
			"runtime_key": "runtime-key-fixture", "profile_digest": "profile-digest-fixture",
			"engine_identity":   engine,
			"broker":            requiredMatrixBroker(),
			"runtime":           requiredMatrixRuntime(endpoint),
			"sharing_effective": requiredMatrixSharing(provider),
		}
	}
	status := func(provider bool) map[string]any {
		return map[string]any{
			"type": "status", "state": "serving", "stage": "composed",
			"broker":            requiredMatrixBroker(),
			"runtime":           requiredMatrixRuntime(endpoint),
			"sharing_effective": requiredMatrixSharing(provider),
			"leases":            []any{requiredMatrixLease(endpoint, engine)},
			"resources":         requiredMatrixResources(),
		}
	}
	// The optional runtime.weights object certifies an instance: both members
	// are required whenever it is present, like the nested provider policy.
	// Certified controls must admit before their missing/null mutations run.
	observation := &EngineWeightsObservation{
		ID: "gguf-sha256:" + strings.Repeat("a", 64), ObservedAt: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
	}
	withWeights := func(frame map[string]any) map[string]any {
		frame["runtime"].(map[string]any)["weights"] = map[string]any{
			"id": observation.ID, "observed_at": observation.ObservedAt.Format(time.RFC3339Nano),
		}
		return frame
	}
	attestedWeights := attested
	attestedWeights.runtime.Weights = observation
	return []requiredMatrixBase{
		{name: "hello/disabled", frame: hello(false), kind: "hello_ok", attested: attested, resolved: resolved, attestedOK: true},
		{name: "hello/provider", frame: hello(true), kind: "hello_ok", attested: attested, resolved: resolved, attestedOK: true},
		{name: "status/disabled", frame: status(false), kind: "status", attested: attested, resolved: resolved, attestedOK: true},
		{name: "status/provider", frame: status(true), kind: "status", attested: attested, resolved: resolved, attestedOK: true},
		{name: "hello/verified-weights", frame: withWeights(hello(false)), kind: "hello_ok", attested: attestedWeights, resolved: resolved, attestedOK: true},
		{name: "status/verified-weights", frame: withWeights(status(false)), kind: "status", attested: attestedWeights, resolved: resolved, attestedOK: true},
		{name: "decode/hello", frame: map[string]any{
			"type": "hello", "protocol_version": 7,
			"client_exec":        map[string]any{"dev": 1, "ino": 2, "size": 3, "mode": 0o755},
			"sharing_configured": requiredMatrixSharing(true),
		}, kind: "decode-only"},
		{name: "decode/lease", frame: map[string]any{
			"type": "lease", "lease_id": "0123456789abcdef0123456789abcdef",
			"lease": requiredMatrixLeaseRecord(endpoint, engine),
		}, kind: "decode-only"},
		{name: "decode/refused", frame: map[string]any{
			"type": "refused", "code": "lease_limit_reached",
			"broker_start_time": map[string]any{"seconds": int64(1000), "microseconds": 0},
		}, kind: "decode-only"},
	}
}

// mutateRequiredMember deletes or nulls member at parentPath. It reports
// whether the path existed in the frame.
func mutateRequiredMember(t *testing.T, frame map[string]any, parentPath []string, member, shape string) bool {
	t.Helper()
	node := frame
	for _, segment := range parentPath {
		key := segment
		if index := strings.Index(segment, "["); index >= 0 {
			key = segment[:index]
		}
		child, ok := node[key]
		if !ok {
			return false
		}
		if strings.Contains(segment, "[0]") {
			rows, ok := child.([]any)
			if !ok || len(rows) == 0 {
				return false
			}
			row, ok := rows[0].(map[string]any)
			if !ok {
				return false
			}
			node = row
			continue
		}
		next, ok := child.(map[string]any)
		if !ok {
			return false
		}
		node = next
	}
	if _, ok := node[member]; !ok {
		return false
	}
	if shape == "missing" {
		delete(node, member)
	} else {
		node[member] = nil
	}
	return true
}

func cloneFrame(t *testing.T, frame map[string]any) map[string]any {
	t.Helper()
	data, err := json.Marshal(frame)
	if err != nil {
		t.Fatal(err)
	}
	var cloned map[string]any
	if err := json.Unmarshal(data, &cloned); err != nil {
		t.Fatal(err)
	}
	return cloned
}

// admitRequiredMatrixFrame mirrors the production admission sequence for one
// mutated frame: wire decode, the caller presence check, then the attested
// envelope validator. Decode-only bases stop after decoding.
func admitRequiredMatrixFrame(t *testing.T, base requiredMatrixBase, frame map[string]any) error {
	t.Helper()
	data, err := json.Marshal(frame)
	if err != nil {
		t.Fatal(err)
	}
	data = append(data, '\n')
	message, err := readSharedWireMessage(bytes.NewReader(data))
	if err != nil {
		return err
	}
	if base.kind == "decode-only" {
		return nil
	}
	if base.kind == "hello_ok" {
		// Mirrors pi_shared_client_darwin.go hello_ok presence check.
		if message.Type != "hello_ok" || message.Broker == nil || message.Runtime == nil || message.EffectiveSharing == nil || message.EngineIdentity == nil {
			return errors.New("broker hello response is incomplete")
		}
		return validateAttestedHelloEnvelope(message, base.resolved.Profile.Runtime)
	}
	// Mirrors pi_shared_operator_darwin.go status presence check.
	if message.Type != "status" || message.Broker == nil || message.Runtime == nil || message.EffectiveSharing == nil {
		return errors.New("broker status response is incomplete")
	}
	return validateAttestedStatusEnvelope(message, base.attested, base.resolved)
}

func TestWireRequiredMembersMatrix(t *testing.T) {
	var cases []requiredMemberCase
	collectRequiredMemberCases(sharedWireStrictSpec(), nil, &cases)
	// Resource required members live in the decoder declaration, exercised
	// here through the status resources object.
	resourceGroups := []struct {
		path    []string
		members []string
	}{
		{[]string{"resources"}, engineResourceRequiredMembers},
		{[]string{"resources", "loaded_model_memory"}, engineResourceMemoryRequiredMembers},
		{[]string{"resources", "inference"}, engineResourceInferenceRequiredMembers},
		{[]string{"resources", "policy"}, append(append([]string(nil), engineResourcePolicyRequiredMembers...), engineResourceProviderActionMembers...)},
	}
	for _, group := range resourceGroups {
		for _, member := range group.members {
			cases = append(cases, requiredMemberCase{
				name:       strings.Join(group.path, ".") + "." + member,
				parentPath: group.path,
				member:     member,
			})
		}
	}
	if len(cases) == 0 {
		t.Fatal("no required members enumerated")
	}
	bases := requiredMatrixBases()
	// Valid controls: every unmutated base must admit.
	for _, base := range bases {
		if err := admitRequiredMatrixFrame(t, base, cloneFrame(t, base.frame)); err != nil {
			t.Fatalf("valid base %s refused: %v", base.name, err)
		}
	}
	ran := 0
	for _, tc := range cases {
		for _, shape := range []string{"missing", "null"} {
			covered := false
			for _, base := range bases {
				frame := cloneFrame(t, base.frame)
				if !mutateRequiredMember(t, frame, tc.parentPath, tc.member, shape) {
					continue
				}
				covered = true
				ran++
				err := admitRequiredMatrixFrame(t, base, frame)
				if shape == "null" && tc.nullable {
					// Nullable members (process argv arrays) are required
					// but null-capable: null must admit.
					if err != nil {
						t.Errorf("nullable %s null refused on base %s: %v", tc.name, base.name, err)
					}
					continue
				}
				if err == nil {
					t.Errorf("admitted %s %s on base %s", tc.name, shape, base.name)
				} else {
					var typed *SharedRuntimeError
					if base.kind != "decode-only" && !errors.As(err, &typed) && !strings.Contains(err.Error(), "incomplete") {
						t.Errorf("%s %s on base %s refused without a typed error: %v", tc.name, shape, base.name, err)
					}
				}
			}
			if !covered {
				t.Errorf("required member %s %s ran on no base", tc.name, shape)
			}
		}
	}
	t.Logf("required-member matrix: %d members, %d admissions decided", len(cases), ran)
}

// TestSharedWireRequiredMatchesOwnerTags pins the required declaration to the
// owner structs: required must equal the non-omitempty JSON members in field
// order. A new owner member without a declaration entry fails here.
func TestSharedWireRequiredMatchesOwnerTags(t *testing.T) {
	spec := sharedWireStrictSpec()
	byPath := map[string]*strictJSONSpec{"": spec}
	var walk func(node *strictJSONSpec, path string)
	walk = func(node *strictJSONSpec, path string) {
		names := make([]string, 0, len(node.object))
		for name := range node.object {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			child := node.object[name]
			if child == nil {
				continue
			}
			childPath := name
			if path != "" {
				childPath = path + "." + name
			}
			if child.elements != nil {
				byPath[childPath+"[0]"] = child.elements
				walk(child.elements, childPath+"[0]")
				continue
			}
			if child.object != nil {
				byPath[childPath] = child
				walk(child, childPath)
			}
		}
	}
	walk(spec, "")
	expect := map[string]reflect.Type{
		"":                                     reflect.TypeOf(sharedWireMessage{}),
		"broker":                               reflect.TypeOf(SharedBrokerIdentity{}),
		"runtime":                              reflect.TypeOf(SharedRuntimeProcessRecord{}),
		"runtime.weights":                      reflect.TypeOf(EngineWeightsObservation{}),
		"sharing_effective":                    reflect.TypeOf(PiRuntimeSharing{}),
		"sharing_configured":                   reflect.TypeOf(PiRuntimeSharing{}),
		"sharing_effective.resource_pressure":  reflect.TypeOf(PiRuntimeResourcePressure{}),
		"sharing_configured.resource_pressure": reflect.TypeOf(PiRuntimeResourcePressure{}),
		"lease":                                reflect.TypeOf(SharedLeaseRecord{}),
		"leases[0]":                            reflect.TypeOf(SharedLeaseStatus{}),
		"engine_identity":                      reflect.TypeOf(SharedRuntimeEngineIdentity{}),
		"broker.start_time":                    reflect.TypeOf(ProcessStartTime{}),
		"runtime.start_time":                   reflect.TypeOf(ProcessStartTime{}),
		"broker_start_time":                    reflect.TypeOf(ProcessStartTime{}),
		"broker.executable_identity":           reflect.TypeOf(FileIdentity{}),
		"runtime.executable_identity":          reflect.TypeOf(FileIdentity{}),
		"client_exec":                          reflect.TypeOf(FileIdentity{}),
		"runtime.pre_exec":                     reflect.TypeOf(ProcessExecShape{}),
		"runtime.post_exec":                    reflect.TypeOf(ProcessExecShape{}),
		"lease.engine_identity":                reflect.TypeOf(SharedRuntimeEngineIdentity{}),
		"lease.client_start_time":              reflect.TypeOf(ProcessStartTime{}),
		"leases[0].engine_identity":            reflect.TypeOf(SharedRuntimeEngineIdentity{}),
		"leases[0].client_start_time":          reflect.TypeOf(ProcessStartTime{}),
	}
	for path, typ := range expect {
		node, ok := byPath[path]
		if !ok {
			t.Errorf("spec lacks node %q", path)
			continue
		}
		var want []string
		var collect func(reflect.Type)
		collect = func(target reflect.Type) {
			for target.Kind() == reflect.Pointer {
				target = target.Elem()
			}
			for i := 0; i < target.NumField(); i++ {
				field := target.Field(i)
				tag := field.Tag.Get("json")
				if tag == "-" {
					continue
				}
				name := strings.Split(tag, ",")[0]
				if field.Anonymous && name == "" {
					collect(field.Type)
					continue
				}
				if name == "" || field.PkgPath != "" {
					continue
				}
				if !strings.Contains(tag, "omitempty") {
					want = append(want, name)
				}
			}
		}
		collect(typ)
		if !reflect.DeepEqual(node.required, want) {
			t.Errorf("node %q required=%v want owner non-omitempty %v", path, node.required, want)
		}
	}
	// The resource subtree keeps its required declaration in the decoder,
	// not the walker spec; the walker must not shadow it.
	for path, node := range byPath {
		if strings.HasPrefix(path, "resources") && len(node.required) != 0 {
			t.Errorf("node %q unexpectedly declares walker required members", path)
		}
	}
}
